// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import { CAPTIONS, LINKS, SUMMARY, isOk } from './script'

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  step(0)
  move('run', { at: 0.2 })
  click('run')
  type('run-text', 'Checking…', { at: '<', speed: 0.02 })
  tl.to(q('run'), { opacity: 0.6, duration: 0.2 }, '<')
  tl.fromTo(
    qa('tile'),
    { backgroundColor: 'rgba(56,189,248,0)' },
    {
      keyframes: [
        { backgroundColor: 'rgba(56,189,248,0.3)', duration: 0.18 },
        { backgroundColor: 'rgba(56,189,248,0)', duration: 0.4 },
      ],
      stagger: { each: 0.07, grid: [4, 3], from: 'start' },
    },
    '<0.1',
  )
  cursorOut('<')

  step(1, '+=0.2')
  type('run-text', 'Check links', { speed: 0.02 })
  tl.to(q('run'), { opacity: 1, duration: 0.2 }, '<')
  tl.fromTo(
    qa('row'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.06, ease: 'power3.out' },
    '<',
  )
  tl.fromTo(
    qa('badge'),
    { opacity: 0, scale: 0.4 },
    { opacity: 1, scale: 1, duration: 0.25, stagger: 0.06, ease: 'back.out(3)' },
    '<0.15',
  )

  step(2, '+=0.4')
  type('summary', SUMMARY, { speed: 0.02 })
  tl.to(
    qa('row-bad'),
    {
      borderColor: 'rgba(251,113,133,0.7)',
      backgroundColor: 'rgba(251,113,133,0.08)',
      duration: 0.3,
      stagger: 0.12,
    },
    '<',
  )
  tl.to(qa('row-ok'), { borderColor: 'var(--demo-tint-4)', duration: 0.3 }, '<')
  final('+=0.3')
  wait(1.8)
}

function Page() {
  return (
    <div className="h-full bg-[#fafafa] px-4 pt-3 text-[#111]">
      <p className="text-[8.5px] font-semibold uppercase tracking-[0.2em] text-[#2563eb]">
        Northwind Docs
      </p>
      <h3 className="mt-1 text-[16px] font-bold tracking-tight">Documentation</h3>
      <div className="mt-3 grid grid-cols-3 gap-1.5">
        {LINKS.map((link) => (
          <span
            key={link.href}
            data-d="tile"
            className="rounded-md border border-black/5 bg-white px-1.5 py-2 text-[9px] font-medium text-[#2563eb] shadow-sm"
          >
            {link.text}
          </span>
        ))}
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Link Checker requesting every link on a docs page and flagging the broken ones"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://docs.northwind.app"
        panelWidth={244}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="flex min-h-0 flex-1 flex-col gap-1.5 p-2">
              <div className="flex items-center gap-2">
                <span
                  data-d="run"
                  className="rounded-md bg-[var(--accent)] px-2.5 py-1 text-[9.5px] font-medium text-canvas"
                >
                  <span data-d="run-text">Check links</span>
                </span>
                <span data-d="summary" className="text-[9.5px] text-ink-soft" />
              </div>
              <ul className="min-h-0 flex-1 space-y-[3px] overflow-hidden">
                {LINKS.map((link) => {
                  const ok = isOk(link)
                  return (
                    <li
                      key={link.href}
                      data-d={`row ${ok ? 'row-ok' : 'row-bad'}`}
                      className="flex h-[18px] items-center gap-1.5 rounded border border-line bg-ink/[0.03] px-1.5 opacity-0"
                    >
                      <span
                        data-d="badge"
                        className="w-7 shrink-0 rounded py-px text-center font-mono text-[8px] font-medium"
                        style={{
                          color: ok ? '#c9c9d3' : '#fff1f2',
                          backgroundColor: ok ? 'var(--demo-tint-8)' : '#be123c',
                        }}
                      >
                        {link.status ?? 'ERR'}
                      </span>
                      <span className="shrink-0 text-[9px] text-ink">{link.text}</span>
                      <span className="min-w-0 truncate font-mono text-[8px] text-muted">
                        {link.href.replace('https://', '')}
                      </span>
                    </li>
                  )
                })}
              </ul>
            </div>
          </div>
        }
      >
        <Page />
      </BrowserChrome>
    </DemoStage>
  )
}
